nextflow_process {
    name "Test Process LINKS"
    script "../main.nf"
    process "LINKS"

    tag "modules"
    tag "modules_nfcore"
    tag "links"

    test("LINKS - sarscov2 test data - contigs") {
        config './nextflow.config'

        when {
            params {
                module_args = "-d 1000,2000,3000,4000,5000,6000,7000,8000,9000,10000,12000,14000,16000,18000,20000"
            }
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fasta/contigs.fasta', checkIfExists: true),
                ]
                input[1] = [
                    [ id:'test'],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true),
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    file(process.out.log[0][1]).name,
                    path(process.out.pairing_issues[0][1]).text == "",
                    process.out.scaffolds_csv,
                    process.out.scaffolds_fasta,
                    process.out.bloom,
                    file(process.out.scaffolds_graph[0][1]).name,
                    process.out.assembly_correspondence,
                    file(process.out.tigpair_checkpoint[0][1]).name,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                    ).match()
                }
            )
        }

    }

    test("LINKS - sarscov2 test data - scaffolds") {
        config './nextflow.config'

        when {
            params {
                module_args = "-d 1000,2000,3000,4000,5000,6000,7000,8000,9000,10000,12000,14000,16000,18000,20000"
            }
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fasta/scaffolds.fasta', checkIfExists: true),
                ]
                input[1] = [
                    [ id:'test'],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fasta/contigs.fasta', checkIfExists: true),
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    file(process.out.log[0][1]).name,
                    file(process.out.pairing_issues[0][1]).text=="",
                    process.out.scaffolds_csv,
                    process.out.scaffolds_fasta,
                    process.out.bloom,
                    file(process.out.scaffolds_graph[0][1]).name,
                    process.out.assembly_correspondence,
                    file(process.out.tigpair_checkpoint[0][1]).text=="",
                    process.out.findAll { key, val -> key.startsWith('versions') }
                    ).match()
                }
            )
        }

    }
    test("LINKS - stub") {

        options "-stub"
        config './nextflow.config'

        when {
            params {
                module_args = "-d 1000,2000,3000,4000,5000,6000,7000,8000,9000,10000,12000,14000,16000,18000,20000"
            }
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true),
                ]
                input[1] = [
                    [ id:'test'],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fasta/contigs.fasta', checkIfExists: true),
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

}

